def extend_facets(add, fields):
    for field, (definition, choices) in CATEGORIES.items():
        add(field, definition, choices, spoiler=field.startswith(('characters.', 'groups.', 'relationships.', 'advisory_details.')))
    eras = fields['world_context.eras']['value_schema']['items']['enum']
    add('world_context.predominant_eras', 'Main substantial story eras by narrative emphasis. Multiple selections require genuinely balanced major timelines; a brief flashback is insufficient. Select only eras also assessed in world_context.eras. Unknown remains null.', eras)
    decades = [str(year) + 's' for year in range(1800, 2200, 10)]
    add('world_context.depicted_decades', 'Substantial established story decades, not release decades. Bounded vocabulary 1800s–2190s; other periods use eras/year bounds. [] means no listed decade identified, not timelessness. Do not guess from production date, a prop or a brief flashback.', decades)
    add('world_context.predominant_decades', 'Main story decades by narrative emphasis; multiple when major timelines are balanced. Each selection must also be in depicted_decades. Outside the bounded vocabulary use eras/year bounds, not the nearest decade. Unknown remains null.', decades)
    for edge in ['earliest', 'latest']:
        field = f'world_context.{edge}_substantial_year'
        fields[field] = {'definition': f'{edge.capitalize()} established calendar year of substantial depicted story settings. Signed historical years: -1 means 1 BCE, 1 means 1 CE; no year zero. Not release date, a fleeting flashback, an inferred exact date from broad era labels, or a promise that all intervening years are depicted. Null if that boundary cannot reasonably be established, including undated prehistoric/fantasy settings. Boundaries can be independently unknown.',
                         'value_schema': {'type': 'integer', 'not': {'const': 0}}, 'applicability': 'all', 'spoiler_sensitive': False}
    fields['representation.established_protagonist_traits']['value_schema']['items']['enum'].append('adult')
    fields['representation.established_protagonist_traits']['definition'] += ' Adult means established adulthood and can overlap older_adult; do not infer age from the performer.'
